# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

# ---
def make_shift(worker, weekday, begin, finish):
    return Shift(worker, weekday, Span(begin * 60, finish * 60))

class TimesheetTests(unittest.TestCase):
    def test_one_line_per_worker_busiest_first(self):
        shifts = [
            make_shift("Bea", "mon", 9, 13),
            make_shift("Ana", "mon", 9, 17),
            make_shift("Ana", "tue", 9, 13),
            make_shift("Bea", "tue", 9, 10)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Ana: 2 shifts, 12.0 hours", "Bea: 2 shifts, 5.0 hours"]
        )

    def test_single_shift_and_one_decimal(self):
        shifts = [Shift("Cyd", "wed", Span(540, 620))]
        self.assertEqual(timesheet_lines(shifts), ["Cyd: 1 shift, 1.3 hours"])

    def test_ties_break_by_name(self):
        shifts = [make_shift("Zed", "mon", 9, 11), make_shift("Amy", "mon", 11, 13)]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Amy: 1 shift, 2.0 hours", "Zed: 1 shift, 2.0 hours"]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.assertRaises(ValueError):
                timesheet_lines([make_shift(name, "mon", 9, 10)])

if __name__ == "__main__":
    unittest.main()
